package com.mannvaasam.security;
import jakarta.servlet.*;import jakarta.servlet.http.*;import org.springframework.security.authentication.UsernamePasswordAuthenticationToken;import org.springframework.security.core.authority.SimpleGrantedAuthority;import org.springframework.security.core.context.SecurityContextHolder;import org.springframework.web.filter.OncePerRequestFilter;import java.io.IOException;import java.util.*;
public class JwtAuthFilter extends OncePerRequestFilter{private final JwtService jwt;public JwtAuthFilter(JwtService j){jwt=j;}protected void doFilterInternal(HttpServletRequest req,HttpServletResponse res,FilterChain chain)throws ServletException,IOException{String h=req.getHeader("Authorization");if(h!=null&&h.startsWith("Bearer "))try{var c=jwt.parse(h.substring(7));var a=List.of(new SimpleGrantedAuthority("ROLE_"+c.get("role",String.class)));SecurityContextHolder.getContext().setAuthentication(new UsernamePasswordAuthenticationToken(c.getSubject(),null,a));}catch(Exception ignored){}chain.doFilter(req,res);}}